import {validateSceneDraft,templateScene} from './scene-model.mjs';
export const VARIANT_TYPES=['natural','filmic','creative','custom','previous'];
export const MAX_VARIANTS=24;
const variantString=(v,max)=>{if(typeof v!=='string'||v.length>max)throw Error('Invalid variant text.');return v;};
export function validateVariant(raw){if(!raw||!VARIANT_TYPES.includes(raw.type))throw Error('Invalid variant.');const id=variantString(raw.id,100);if(!id)throw Error('Missing variant ID.');return {id,type:raw.type,name:variantString(raw.name,180),draft:{...validateSceneDraft(raw.draft),applied:false}};}
export function validateVariants(raw){if(!Array.isArray(raw)||raw.length>MAX_VARIANTS)throw Error('Too many scene variants.');const ids=new Set();return raw.map(v=>{const next=validateVariant(v);if(ids.has(next.id))throw Error('Duplicate variant ID.');ids.add(next.id);return next;});}
export function validateFavorites(raw){if(!raw||raw.schema!=='artoftomworks.scene-dna.scene-favorites'||raw.version!==1||!Array.isArray(raw.entries)||raw.entries.length>50)throw Error('Invalid saved scene ideas.');const ids=new Set();return {schema:raw.schema,version:1,entries:raw.entries.map(v=>{const next=validateVariant(v);if(!next.name.trim()||!next.draft.text.trim()||ids.has(next.id))throw Error('Invalid saved idea.');ids.add(next.id);return next;})};}
export function templateVariants(base,settings,duration){const directions={natural:'Use a small, believable motion of one element already established in the scene; keep the pacing unhurried.',filmic:'Give one existing subject or scene element a clear action and a settled ending, using cinematic pacing within the stated camera plan.',creative:'Find a different detail already present and give it one subtle, fitting movement. Preserve the established lighting, camera and objects; introduce no new content.'};return Object.entries(directions).map(([type,direction])=>{const result=templateScene(base,settings,duration);return {type,videoPrompt:result.videoPrompt+'\n'+direction,summary:direction,observations:''};});}
export function validateVariantReply(raw){if(!raw||!Array.isArray(raw.variants)||raw.variants.length!==3||typeof raw.observations!=='string'||raw.observations.length>2000)throw Error('The model did not return three complete scene variants.');const types=new Set(),texts=new Set();const variants=raw.variants.map(v=>{if(!['natural','filmic','creative'].includes(v.type)||types.has(v.type)||typeof v.videoPrompt!=='string'||!v.videoPrompt.trim()||v.videoPrompt.length>12000||typeof v.summary!=='string'||v.summary.length>2000)throw Error('Invalid scene variant response.');types.add(v.type);const key=v.videoPrompt.trim().toLowerCase().replace(/\s+/g,' ');if(texts.has(key))throw Error('The model repeated a scene variant. Try again.');texts.add(key);return {type:v.type,videoPrompt:v.videoPrompt,summary:v.summary,observations:raw.observations};});return ['natural','filmic','creative'].map(type=>variants.find(v=>v.type===type));}
